// @FIGURE_CODE_BEGIN
// green vertical plane x=1 → PlaneGeometry rectangle in world plane X=1, green transparent double-sided
// red vertical plane y=-2 → PlaneGeometry rectangle in world plane Z=-2, red transparent double-sided
// blue horizontal plane z=2 → PlaneGeometry rectangle in world plane Y=2, blue transparent double-sided
// plane outlines → LineLoop rectangles, hidden until selected/highlighted
// glow highlights → slightly larger transparent plane meshes, hidden until selected/highlighted
// central solution point → black SphereGeometry at math (1,-2,2)
// leader line → thin black Line from point toward coordinate label
// equation/coordinate/warning/badge text → addLabel HTML labels positioned in 3D

const mathToWorld = (x, y, z) => new THREE.Vector3(x, z, y);

const COLORS = {
  x: 0x2fb84a,
  y: 0xe51b23,
  z: 0x057fa3,
  black: 0x000000,
  amber: 0xffb000
};

const root = new THREE.Group();
scene.add(root);

const xMin = -1.8, xMax = 4.0;
const yMin = -4.2, yMax = 1.6;
const zMin = -0.4, zMax = 4.2;
const px = 1, py = -2, pz = 2;
const pointWorld = mathToWorld(px, py, pz);

function makePlaneMaterial(color) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: true,
    opacity: 0.91,
    side: THREE.DoubleSide,
    depthWrite: false
  });
}

function makeGlowMaterial(color) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: true,
    opacity: 0.22,
    side: THREE.DoubleSide,
    depthWrite: false
  });
}

function geometryFromCorners(corners) {
  const geom = new THREE.BufferGeometry();
  const verts = new Float32Array([
    corners[0].x, corners[0].y, corners[0].z,
    corners[1].x, corners[1].y, corners[1].z,
    corners[2].x, corners[2].y, corners[2].z,
    corners[0].x, corners[0].y, corners[0].z,
    corners[2].x, corners[2].y, corners[2].z,
    corners[3].x, corners[3].y, corners[3].z
  ]);
  geom.setAttribute('position', new THREE.BufferAttribute(verts, 3));
  geom.computeVertexNormals();
  geom.computeBoundingBox();
  geom.computeBoundingSphere();
  return geom;
}

function makeLineLoop(corners, color) {
  const pts = [...corners, corners[0]];
  const geom = new THREE.BufferGeometry().setFromPoints(pts);
  const mat = new THREE.LineBasicMaterial({ color, linewidth: 2 });
  return new THREE.Line(geom, mat);
}

function expandedCorners(corners, center, factor) {
  return corners.map(c => center.clone().add(c.clone().sub(center).multiplyScalar(factor)));
}

const xCorners = [
  mathToWorld(1, yMin, zMin),
  mathToWorld(1, yMax, zMin),
  mathToWorld(1, yMax, zMax),
  mathToWorld(1, yMin, zMax)
];
const yCorners = [
  mathToWorld(xMin, -2, zMin),
  mathToWorld(xMax, -2, zMin),
  mathToWorld(xMax, -2, zMax),
  mathToWorld(xMin, -2, zMax)
];
const zCorners = [
  mathToWorld(xMin, yMin, 2),
  mathToWorld(xMax, yMin, 2),
  mathToWorld(xMax, yMax, 2),
  mathToWorld(xMin, yMax, 2)
];

const xCenter = mathToWorld(1, (yMin + yMax) / 2, (zMin + zMax) / 2);
const yCenter = mathToWorld((xMin + xMax) / 2, -2, (zMin + zMax) / 2);
const zCenter = mathToWorld((xMin + xMax) / 2, (yMin + yMax) / 2, 2);

const xPlane = new THREE.Mesh(geometryFromCorners(xCorners), makePlaneMaterial(COLORS.x));
const yPlane = new THREE.Mesh(geometryFromCorners(yCorners), makePlaneMaterial(COLORS.y));
const zPlane = new THREE.Mesh(geometryFromCorners(zCorners), makePlaneMaterial(COLORS.z));
xPlane.renderOrder = 3;
yPlane.renderOrder = 2;
zPlane.renderOrder = 1;
root.add(zPlane, yPlane, xPlane);

const xGlow = new THREE.Mesh(geometryFromCorners(expandedCorners(xCorners, xCenter, 1.055)), makeGlowMaterial(COLORS.x));
const yGlow = new THREE.Mesh(geometryFromCorners(expandedCorners(yCorners, yCenter, 1.055)), makeGlowMaterial(COLORS.y));
const zGlow = new THREE.Mesh(geometryFromCorners(expandedCorners(zCorners, zCenter, 1.055)), makeGlowMaterial(COLORS.z));
xGlow.renderOrder = 8;
yGlow.renderOrder = 8;
zGlow.renderOrder = 8;
xGlow.visible = yGlow.visible = zGlow.visible = false;
root.add(xGlow, yGlow, zGlow);

const xOutline = makeLineLoop(xCorners, 0x126b25);
const yOutline = makeLineLoop(yCorners, 0x8b0b10);
const zOutline = makeLineLoop(zCorners, 0x034d63);
xOutline.visible = yOutline.visible = zOutline.visible = false;
root.add(xOutline, yOutline, zOutline);

const point = new THREE.Mesh(
  new THREE.SphereGeometry(0.105, 32, 16),
  new THREE.MeshBasicMaterial({ color: COLORS.black })
);
point.position.copy(pointWorld);
point.renderOrder = 20;
root.add(point);

const leaderEnd = mathToWorld(2.72, -1.18, 4.55);
const leaderGeom = new THREE.BufferGeometry().setFromPoints([pointWorld, leaderEnd]);
const leader = new THREE.Line(leaderGeom, new THREE.LineBasicMaterial({ color: COLORS.black }));
leader.renderOrder = 21;
root.add(leader);

const hitSpheres = {};
function addPlaneHitSphere(name, pos, color) {
  const mesh = new THREE.Mesh(
    new THREE.SphereGeometry(0.17, 16, 8),
    new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.0, depthWrite: false })
  );
  mesh.position.copy(pos);
  mesh.visible = true;
  root.add(mesh);
  hitSpheres[name] = mesh;
  registerInteractive(mesh, {
    title: name === 'x' ? 'x = 1 plane' : name === 'y' ? 'y plane' : 'z = 2 plane',
    tooltip: 'Click to highlight this equation',
    body: name === 'x'
      ? 'The equation x = 1 fixes the x-coordinate. The y- and z-coordinates remain free on the green sheet.'
      : name === 'y'
        ? 'The y-equation fixes only y. In the printed figure it is labeled y = -2, which conflicts with the printed point label.'
        : 'The equation z = 2 fixes the height coordinate, making the blue horizontal sheet.',
    onClick: () => selectPlane(name)
  });
}
addPlaneHitSphere('x', mathToWorld(1.08, 1.87, 4.42), COLORS.x);
addPlaneHitSphere('y', mathToWorld(1.1, -2.35, -0.85), COLORS.y);
addPlaneHitSphere('z', mathToWorld(4.3, -0.6, 2.12), COLORS.z);

registerInteractive(xPlane, {
  title: 'x = 1 plane',
  tooltip: 'Green sheet: x is fixed',
  body: 'Every point on this green plane has x-coordinate 1. The other two coordinates can vary.',
  onClick: () => selectPlane('x')
});
registerInteractive(yPlane, {
  title: 'y plane',
  tooltip: 'Red sheet: y is fixed',
  body: 'Every point on this red plane has the displayed y-coordinate. A single plane alone is not a unique solution.',
  onClick: () => selectPlane('y')
});
registerInteractive(zPlane, {
  title: 'z = 2 plane',
  tooltip: 'Blue sheet: z is fixed',
