  onClick: () => selectPlane('z')
});

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.68
});

const xLabel = addLabel('<i>x</i> = 1', mathToWorld(1.08, 1.88, 4.47), {
  color: '#2fb84a',
  fontSize: '20px',
  offset: [4, -2]
});
const yLabel = addLabel('<i>y</i> = −2', mathToWorld(1.05, -2.35, -0.84), {
  color: '#e51b23',
  fontSize: '20px',
  offset: [0, 14]
});
const zLabel = addLabel('<i>z</i> = 2', mathToWorld(4.28, -0.52, 2.08), {
  color: '#057fa3',
  fontSize: '20px',
  offset: [15, 0]
});
const coordLabel = addLabel('(1, −1, 2)', leaderEnd, {
  color: '#111',
  fontSize: '20px',
  offset: [18, -16]
});
const warningLabel = addLabel('⚠ printed labels conflict:<br>(1, −1, 2) is not on <i>y</i> = −2', mathToWorld(-1.4, -4.7, 3.75), {
  color: '#7a4b00',
  fontSize: '12px',
  background: 'rgba(255,245,205,0.94)',
  offset: [-22, -8]
});
const badgeLabel = addLabel('', mathToWorld(2.25, -0.25, 3.15), {
  color: '#111',
  fontSize: '13px',
  background: 'rgba(255,255,255,0.92)',
  offset: [0, 0]
});
badgeLabel.div.style.border = '1px solid #777';
badgeLabel.div.style.display = 'none';

for (const entry of [xLabel, yLabel, zLabel]) {
  entry.div.style.pointerEvents = 'auto';
  entry.div.style.cursor = 'pointer';
  entry.div.style.padding = '1px 4px';
  entry.div.style.borderRadius = '3px';
}
xLabel.div.addEventListener('click', () => selectPlane('x'));
yLabel.div.addEventListener('click', () => selectPlane('y'));
zLabel.div.addEventListener('click', () => selectPlane('z'));

let selectedPlane = null;
let pulseT = 0;

function setPlaneTint(mesh, baseColor, selected) {
  mesh.material.color.setHex(baseColor);
  mesh.material.opacity = selected ? 0.98 : 0.91;
}

function selectPlane(name) {
  selectedPlane = name;
  xOutline.visible = name === 'x';
  yOutline.visible = name === 'y';
  zOutline.visible = name === 'z';
  xGlow.visible = name === 'x';
  yGlow.visible = name === 'y';
  zGlow.visible = name === 'z';

  setPlaneTint(xPlane, COLORS.x, name === 'x');
  setPlaneTint(yPlane, COLORS.y, name === 'y');
  setPlaneTint(zPlane, COLORS.z, name === 'z');

  if (name === 'x') {
    badgeLabel.div.innerHTML = '<b style="color:#2fb84a">x fixed</b><br>y and z free';
    badgeLabel.pos.copy(mathToWorld(1.22, -0.25, 3.35));
    showPopup('x = 1', 'The green equation fixes only the x-coordinate, leaving a whole plane of possible points.');
  } else if (name === 'y') {
    const txt = document.getElementById('labelCorrection').value === 'Correct red label to y = -1' ? 'y = −1' : 'y = −2';
    badgeLabel.div.innerHTML = `<b style="color:#e51b23">${txt} fixed</b><br>x and z free`;
    badgeLabel.pos.copy(mathToWorld(2.55, -2.08, 3.0));
    showPopup('y plane', 'The red equation fixes only the y-coordinate. Check that the point label uses the same y-value.');
  } else if (name === 'z') {
    badgeLabel.div.innerHTML = '<b style="color:#057fa3">z fixed</b><br>x and y free';
    badgeLabel.pos.copy(mathToWorld(2.55, -0.55, 2.2));
    showPopup('z = 2', 'The blue equation fixes the height coordinate z = 2.');
  }
  badgeLabel.div.style.display = '';
}

function setGroupVisibleForPlane(name, visible) {
  if (name === 'x') {
    xPlane.visible = xGlow.visible = visible && selectedPlane === 'x';
    xOutline.visible = visible && selectedPlane === 'x';
    xLabel.div.style.display = visible ? '' : 'none';
    hitSpheres.x.visible = visible;
    if (visible && selectedPlane !== 'x') xPlane.visible = true;
  }
  if (name === 'y') {
    yPlane.visible = yGlow.visible = visible && selectedPlane === 'y';
    yOutline.visible = visible && selectedPlane === 'y';
    yLabel.div.style.display = visible ? '' : 'none';
    hitSpheres.y.visible = visible;
    if (visible && selectedPlane !== 'y') yPlane.visible = true;
  }
  if (name === 'z') {
    zPlane.visible = zGlow.visible = visible && selectedPlane === 'z';
    zOutline.visible = visible && selectedPlane === 'z';
    zLabel.div.style.display = visible ? '' : 'none';
    hitSpheres.z.visible = visible;
    if (visible && selectedPlane !== 'z') zPlane.visible = true;
  }
}

function applyVisibility() {
  const sx = document.getElementById('showXPlane').checked;
  const sy = document.getElementById('showYPlane').checked;
  const sz = document.getElementById('showZPlane').checked;

  xPlane.visible = sx;
  yPlane.visible = sy;
  zPlane.visible = sz;
  xLabel.div.style.display = sx ? '' : 'none';
  yLabel.div.style.display = sy ? '' : 'none';
  zLabel.div.style.display = sz ? '' : 'none';
  hitSpheres.x.visible = sx;
  hitSpheres.y.visible = sy;
  hitSpheres.z.visible = sz;

  xGlow.visible = sx && selectedPlane === 'x';
  yGlow.visible = sy && selectedPlane === 'y';
  zGlow.visible = sz && selectedPlane === 'z';
  xOutline.visible = sx && selectedPlane === 'x';
  yOutline.visible = sy && selectedPlane === 'y';
  zOutline.visible = sz && selectedPlane === 'z';

  if ((selectedPlane === 'x' && !sx) || (selectedPlane === 'y' && !sy) || (selectedPlane === 'z' && !sz)) {
    badgeLabel.div.style.display = 'none';
