  }
}

function applyLabelCorrection() {
  const state = document.getElementById('labelCorrection').value;
  if (state === 'Correct red label to y = -1') {
    yLabel.div.innerHTML = '<i>y</i> = −1';
    coordLabel.div.innerHTML = '(1, −1, 2)';
    warningLabel.div.style.display = 'none';
