const mathToWorld = (x, y, z) => new THREE.Vector3(x, z, y);

const COLORS = {
  x: 0x2fb84a,
  y: 0xe51b23,
  z: 0x057fa3,
  black: 0x000000,
  amber: 0xffb000
};

const root = new THREE.Group();
scene.add(root);

const xMin = -1.8, xMax = 4.0;
const yMin = -4.2, yMax = 1.6;
const zMin = -0.4, zMax = 4.2;
const px = 1, py = -2, pz = 2;
const pointWorld = mathToWorld(px, py, pz);

function makePlaneMaterial(color) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: true,
    opacity: 0.91,
    side: THREE.DoubleSide,
    depthWrite: false
  });
}

function makeGlowMaterial(color) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: true,
    opacity: 0.22,
    side: THREE.DoubleSide,
    depthWrite: false
  });
}

function geometryFromCorners(corners) {
  const geom = new THREE.BufferGeometry();
  const verts = new Float32Array([
    corners[0].x, corners[0].y, corners[0].z,
    corners[1].x, corners[1].y, corners[1].z,
    corners[2].x, corners[2].y, corners[2].z,
    corners[0].x, corners[0].y, corners[0].z,
    corners[2].x, corners[2].y, corners[2].z,
    corners[3].x, corners[3].y, corners[3].z
  ]);
  geom.setAttribute('position', new THREE.BufferAttribute(verts, 3));
  geom.computeVertexNormals();
  geom.computeBoundingBox();
  geom.computeBoundingSphere();
  return geom;
}

function makeLineLoop(corners, color) {
  const pts = [...corners, corners[0]];
  const geom = new THREE.BufferGeometry().setFromPoints(pts);
  const mat = new THREE.LineBasicMaterial({ color, linewidth: 2 });
  return new THREE.Line(geom, mat);
}

function expandedCorners(corners, center, factor) {
  return corners.map(c => center.clone().add(c.clone().sub(center).multiplyScalar(factor)));
}

const xCorners = [
  mathToWorld(1, yMin, zMin),
  mathToWorld(1, yMax, zMin),
  mathToWorld(1, yMax, zMax),
  mathToWorld(1, yMin, zMax)
];
const yCorners = [
  mathToWorld(xMin, -2, zMin),
  mathToWorld(xMax, -2, zMin),
  mathToWorld(xMax, -2, zMax),
  mathToWorld(xMin, -2, zMax)
];
const zCorners = [
  mathToWorld(xMin, yMin, 2),
  mathToWorld(xMax, yMin, 2),
  mathToWorld(xMax, yMax, 2),
  mathToWorld(xMin, yMax, 2)
];

const xCenter = mathToWorld(1, (yMin + yMax) / 2, (zMin + zMax) / 2);
const yCenter = mathToWorld((xMin + xMax) / 2, -2, (zMin + zMax) / 2);
const zCenter = mathToWorld((xMin + xMax) / 2, (yMin + yMax) / 2, 2);

const xPlane = new THREE.Mesh(geometryFromCorners(xCorners), makePlaneMaterial(COLORS.x));
const yPlane = new THREE.Mesh(geometryFromCorners(yCorners), makePlaneMaterial(COLORS.y));
const zPlane = new THREE.Mesh(geometryFromCorners(zCorners), makePlaneMaterial(COLORS.z));
xPlane.renderOrder = 3;
yPlane.renderOrder = 2;
zPlane.renderOrder = 1;
root.add(zPlane, yPlane, xPlane);

const xGlow = new THREE.Mesh(geometryFromCorners(expandedCorners(xCorners, xCenter, 1.055)), makeGlowMaterial(COLORS.x));
const yGlow = new THREE.Mesh(geometryFromCorners(expandedCorners(yCorners, yCenter, 1.055)), makeGlowMaterial(COLORS.y));
const zGlow = new THREE.Mesh(geometryFromCorners(expandedCorners(zCorners, zCenter, 1.055)), makeGlowMaterial(COLORS.z));
xGlow.renderOrder = 8;
yGlow.renderOrder = 8;
zGlow.renderOrder = 8;
xGlow.visible = yGlow.visible = zGlow.visible = false;
root.add(xGlow, yGlow, zGlow);

const xOutline = makeLineLoop(xCorners, 0x126b25);
const yOutline = makeLineLoop(yCorners, 0x8b0b10);
const zOutline = makeLineLoop(zCorners, 0x034d63);
xOutline.visible = yOutline.visible = zOutline.visible = false;
root.add(xOutline, yOutline, zOutline);

const point = new THREE.Mesh(
  new THREE.SphereGeometry(0.105, 32, 16),
  new THREE.MeshBasicMaterial({ color: COLORS.black })
);
point.position.copy(pointWorld);
point.renderOrder = 20;
root.add(point);

const leaderEnd = mathToWorld(2.72, -1.18, 4.55);
const leaderGeom = new THREE.BufferGeometry().setFromPoints([pointWorld, leaderEnd]);
const leader = new THREE.Line(leaderGeom, new THREE.LineBasicMaterial({ color: COLORS.black }));
leader.renderOrder = 21;
root.add(leader);

const hitSpheres = {};
function addPlaneHitSphere(name, pos, color) {
  const mesh = new THREE.Mesh(
    new THREE.SphereGeometry(0.17, 16, 8),
    new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.0, depthWrite: false })
  );
  mesh.position.copy(pos);
  mesh.visible = true;
  root.add(mesh);
  hitSpheres[name] = mesh;
  registerInteractive(mesh, {
    title: name === 'x' ? 'x = 1 plane' : name === 'y' ? 'y plane' : 'z = 2 plane',
    tooltip: 'Click to highlight this equation',
    body: name === 'x'
      ? 'The equation x = 1 fixes the x-coordinate. The y- and z-coordinates remain free on the green sheet.'
      : name === 'y'
        ? 'The y-equation fixes only y. In the printed figure it is labeled y = -2, which conflicts with the printed point label.'
        : 'The equation z = 2 fixes the height coordinate, making the blue horizontal sheet.',
    onClick: () => selectPlane(name)
  });
}
addPlaneHitSphere('x', mathToWorld(1.08, 1.87, 4.42), COLORS.x);
addPlaneHitSphere('y', mathToWorld(1.1, -2.35, -0.85), COLORS.y);
addPlaneHitSphere('z', mathToWorld(4.3, -0.6, 2.12), COLORS.z);

registerInteractive(xPlane, {
  title: 'x = 1 plane',
  tooltip: 'Green sheet: x is fixed',
  body: 'Every point on this green plane has x-coordinate 1. The other two coordinates can vary.',
  onClick: () => selectPlane('x')
});
registerInteractive(yPlane, {
  title: 'y plane',
  tooltip: 'Red sheet: y is fixed',
  body: 'Every point on this red plane has the displayed y-coordinate. A single plane alone is not a unique solution.',
  onClick: () => selectPlane('y')
});
registerInteractive(zPlane, {
  title: 'z = 2 plane',
  tooltip: 'Blue sheet: z is fixed',
  body: 'Every point on this blue horizontal plane has z-coordinate 2.',
  onClick: () => selectPlane('z')
});

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.68
});

const xLabel = addLabel('<i>x</i> = 1', mathToWorld(1.08, 1.88, 4.47), {
  color: '#2fb84a',
  fontSize: '20px',
  offset: [4, -2]
});
const yLabel = addLabel('<i>y</i> = −2', mathToWorld(1.05, -2.35, -0.84), {
  color: '#e51b23',
  fontSize: '20px',
  offset: [0, 14]
});
const zLabel = addLabel('<i>z</i> = 2', mathToWorld(4.28, -0.52, 2.08), {
  color: '#057fa3',
  fontSize: '20px',
  offset: [15, 0]
});
const coordLabel = addLabel('(1, −1, 2)', leaderEnd, {
  color: '#111',
  fontSize: '20px',
  offset: [18, -16]
});
const warningLabel = addLabel('⚠ printed labels conflict:<br>(1, −1, 2) is not on <i>y</i> = −2', mathToWorld(-1.4, -4.7, 3.75), {
  color: '#7a4b00',
  fontSize: '12px',
  background: 'rgba(255,245,205,0.94)',
  offset: [-22, -8]
});
const badgeLabel = addLabel('', mathToWorld(2.25, -0.25, 3.15), {
  color: '#111',
  fontSize: '13px',
  background: 'rgba(255,255,255,0.92)',
  offset: [0, 0]
});
badgeLabel.div.style.border = '1px solid #777';
badgeLabel.div.style.display = 'none';

for (const entry of [xLabel, yLabel, zLabel]) {
  entry.div.style.pointerEvents = 'auto';
  entry.div.style.cursor = 'pointer';
  entry.div.style.padding = '1px 4px';
  entry.div.style.borderRadius = '3px';
}
xLabel.div.addEventListener('click', () => selectPlane('x'));
yLabel.div.addEventListener('click', () => selectPlane('y'));
zLabel.div.addEventListener('click', () => selectPlane('z'));

let selectedPlane = null;
let pulseT = 0;

function setPlaneTint(mesh, baseColor, selected) {
  mesh.material.color.setHex(baseColor);
  mesh.material.opacity = selected ? 0.98 : 0.91;
}

function selectPlane(name) {
  selectedPlane = name;
  xOutline.visible = name === 'x';
  yOutline.visible = name === 'y';
  zOutline.visible = name === 'z';
  xGlow.visible = name === 'x';
  yGlow.visible = name === 'y';
  zGlow.visible = name === 'z';

  setPlaneTint(xPlane, COLORS.x, name === 'x');
  setPlaneTint(yPlane, COLORS.y, name === 'y');
  setPlaneTint(zPlane, COLORS.z, name === 'z');

  if (name === 'x') {
    badgeLabel.div.innerHTML = '<b style="color:#2fb84a">x fixed</b><br>y and z free';
    badgeLabel.pos.copy(mathToWorld(1.22, -0.25, 3.35));
    showPopup('x = 1', 'The green equation fixes only the x-coordinate, leaving a whole plane of possible points.');
  } else if (name === 'y') {
    const txt = document.getElementById('labelCorrection').value === 'Correct red label to y = -1' ? 'y = −1' : 'y = −2';
    badgeLabel.div.innerHTML = `<b style="color:#e51b23">${txt} fixed</b><br>x and z free`;
    badgeLabel.pos.copy(mathToWorld(2.55, -2.08, 3.0));
    showPopup('y plane', 'The red equation fixes only the y-coordinate. Check that the point label uses the same y-value.');
  } else if (name === 'z') {
    badgeLabel.div.innerHTML = '<b style="color:#057fa3">z fixed</b><br>x and y free';
    badgeLabel.pos.copy(mathToWorld(2.55, -0.55, 2.2));
    showPopup('z = 2', 'The blue equation fixes the height coordinate z = 2.');
  }
  badgeLabel.div.style.display = '';
}

function setGroupVisibleForPlane(name, visible) {
  if (name === 'x') {
    xPlane.visible = xGlow.visible = visible && selectedPlane === 'x';
    xOutline.visible = visible && selectedPlane === 'x';
    xLabel.div.style.display = visible ? '' : 'none';
    hitSpheres.x.visible = visible;
    if (visible && selectedPlane !== 'x') xPlane.visible = true;
  }
  if (name === 'y') {
    yPlane.visible = yGlow.visible = visible && selectedPlane === 'y';
    yOutline.visible = visible && selectedPlane === 'y';
    yLabel.div.style.display = visible ? '' : 'none';
    hitSpheres.y.visible = visible;
    if (visible && selectedPlane !== 'y') yPlane.visible = true;
  }
  if (name === 'z') {
    zPlane.visible = zGlow.visible = visible && selectedPlane === 'z';
    zOutline.visible = visible && selectedPlane === 'z';
    zLabel.div.style.display = visible ? '' : 'none';
    hitSpheres.z.visible = visible;
    if (visible && selectedPlane !== 'z') zPlane.visible = true;
  }
}

function applyVisibility() {
  const sx = document.getElementById('showXPlane').checked;
  const sy = document.getElementById('showYPlane').checked;
  const sz = document.getElementById('showZPlane').checked;

  xPlane.visible = sx;
  yPlane.visible = sy;
  zPlane.visible = sz;
  xLabel.div.style.display = sx ? '' : 'none';
  yLabel.div.style.display = sy ? '' : 'none';
  zLabel.div.style.display = sz ? '' : 'none';
  hitSpheres.x.visible = sx;
  hitSpheres.y.visible = sy;
  hitSpheres.z.visible = sz;

  xGlow.visible = sx && selectedPlane === 'x';
  yGlow.visible = sy && selectedPlane === 'y';
  zGlow.visible = sz && selectedPlane === 'z';
  xOutline.visible = sx && selectedPlane === 'x';
  yOutline.visible = sy && selectedPlane === 'y';
  zOutline.visible = sz && selectedPlane === 'z';

  if ((selectedPlane === 'x' && !sx) || (selectedPlane === 'y' && !sy) || (selectedPlane === 'z' && !sz)) {
    badgeLabel.div.style.display = 'none';
  } else if (selectedPlane) {
    badgeLabel.div.style.display = '';
  }
}

function applyLabelCorrection() {
  const state = document.getElementById('labelCorrection').value;
  if (state === 'Correct red label to y = -1') {
    yLabel.div.innerHTML = '<i>y</i> = −1';
    coordLabel.div.innerHTML = '(1, −1, 2)';
    warningLabel.div.style.display = 'none';
  } else if (state === 'Correct point to (1, -2, 2)') {
    yLabel.div.innerHTML = '<i>y</i> = −2';
    coordLabel.div.innerHTML = '(1, −2, 2)';
    warningLabel.div.style.display = 'none';
  } else {
    yLabel.div.innerHTML = '<i>y</i> = −2';
    coordLabel.div.innerHTML = '(1, −1, 2)';
    warningLabel.div.style.display = '';
  }
  if (selectedPlane === 'y') selectPlane('y');
}

document.getElementById('showXPlane').addEventListener('change', applyVisibility);
document.getElementById('showYPlane').addEventListener('change', applyVisibility);
document.getElementById('showZPlane').addEventListener('change', applyVisibility);
document.getElementById('labelCorrection').addEventListener('change', () => {
  applyLabelCorrection();
  applyVisibility();
});

const steps = [
  {
    title: 'Printed figure',
    narration: 'All three planes are visible as in the source figure. The black point is labeled (1, -1, 2), but the red plane is labeled y = -2, so the warning marks the inconsistency.',
    state: { showXPlane: true, showYPlane: true, showZPlane: true, labelCorrection: 'Printed conflict' }
  },
  {
    title: 'Isolate one equation',
