    state: { showXPlane: true, showYPlane: false, showZPlane: false, labelCorrection: 'Printed conflict' }
  },
  {
    title: 'Planes intersect to locate a point',
    narration: 'Restore all three sheets. Their common intersection represents the ordered triple that satisfies all three equations.',
    state: { showXPlane: true, showYPlane: true, showZPlane: true, labelCorrection: 'Printed conflict' }
  },
  {
    title: 'Correct the inconsistency',
    narration: 'Switch to a corrected label. Either the red equation must be y = -1 for the printed point, or the point must be labeled (1, -2, 2) for the printed red equation.',
    state: { showXPlane: true, showYPlane: true, showZPlane: true, labelCorrection: 'Correct point to (1, -2, 2)' }
  }
];

function goToStep(i) {
  const step = steps[i] || steps[0];
  document.getElementById('showXPlane').checked = step.state.showXPlane;
  document.getElementById('showYPlane').checked = step.state.showYPlane;
  document.getElementById('showZPlane').checked = step.state.showZPlane;
  document.getElementById('labelCorrection').value = step.state.labelCorrection;
  document.getElementById('demoTitle').textContent = step.title;
  document.getElementById('demoText').textContent = step.narration;
  for (let j = 0; j < 4; j++) document.getElementById('step' + j).classList.toggle('active', j === i);
  applyLabelCorrection();
  applyVisibility();
  if (i === 1) selectPlane('x');
  if (i === 2) selectedPlane = null;
  if (i === 2) {
    xOutline.visible = yOutline.visible = zOutline.visible = false;
    xGlow.visible = yGlow.visible = zGlow.visible = false;
    badgeLabel.div.style.display = 'none';
    hidePopup();
