  if (i === 3) selectPlane('y');
  setCameraView({
    projection: 'orthographic',
    axisScreenAngles: { x: 30, z: 30 },
    rollDeg: 0,
    heightFraction: 0.68
  });
}
window.goToStep = goToStep;

for (let i = 0; i < 4; i++) {
  document.getElementById('step' + i).addEventListener('click', () => goToStep(i));
}
document.getElementById('step0').classList.add('active');

const oldAnimateHook = controls.update.bind(controls);
controls.update = function() {
  pulseT += 0.035;
  const op = 0.18 + 0.08 * Math.sin(pulseT);
  xGlow.material.opacity = op;
  yGlow.material.opacity = op;
  zGlow.material.opacity = op;
  oldAnimateHook();
};

applyLabelCorrection();
applyVisibility();
