// @FIGURE_CODE_BEGIN
// green plane x=1 → custom BufferGeometry parallelogram in plane X=constant, saturated green transparent material
// red plane y=-2 → custom BufferGeometry parallelogram in plane Z=constant, saturated red transparent material
// blue plane z=2 → custom BufferGeometry parallelogram in plane Y=constant, saturated blue transparent material
// plane highlight outlines → Line rectangles, hidden until a plane is selected
// plane highlight washes → slightly expanded transparent plane meshes, hidden until a plane is selected
// printed point → black SphereGeometry placed at the printed coordinate (1,−1,2)
// leader line → thin black Line from point to printed coordinate label
// printed labels → addLabel HTML labels for (1,−1,2), x=1, y=−2, z=2
// optional teaching note → addLabel note, hidden by default and only shown by toggle/step

const S = 0.55;
const mathToWorld = (x, y, z) => new THREE.Vector3((x - 1) * S, (z - 2) * S, (y + 1.2) * S);

const COLORS = {
  x: 0x27b83f,
  y: 0xe51d25,
  z: 0x087fa2,
  xDark: 0x0d8c27,
  yDark: 0xa70b12,
  zDark: 0x035a74,
  black: 0x000000
};

const root = new THREE.Group();
scene.add(root);

const xMin = -1.85, xMax = 3.75;
const yMin = -3.55, yMax = 1.45;
const zMin = -0.35, zMax = 3.85;

const printedPoint = { x: 1, y: -1, z: 2 };
const pointWorld = mathToWorld(printedPoint.x, printedPoint.y, printedPoint.z);

function makePlaneMaterial(color) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: true,
    opacity: 0.94,
    side: THREE.DoubleSide,
    depthWrite: false
  });
}

function makeGlowMaterial(color) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: true,
    opacity: 0.24,
    side: THREE.DoubleSide,
    depthWrite: false
  });
}

function geometryFromCorners(corners) {
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.BufferAttribute(new Float32Array([
    corners[0].x, corners[0].y, corners[0].z,
    corners[1].x, corners[1].y, corners[1].z,
    corners[2].x, corners[2].y, corners[2].z,
    corners[0].x, corners[0].y, corners[0].z,
    corners[2].x, corners[2].y, corners[2].z,
    corners[3].x, corners[3].y, corners[3].z
  ]), 3));
  geom.computeVertexNormals();
  geom.computeBoundingBox();
  geom.computeBoundingSphere();
  return geom;
}

function expandedCorners(corners, factor) {
  const c = new THREE.Vector3();
  for (const p of corners) c.add(p);
  c.multiplyScalar(1 / corners.length);
  return corners.map(p => c.clone().add(p.clone().sub(c).multiplyScalar(factor)));
}

function makeOutline(corners, color) {
  const geom = new THREE.BufferGeometry().setFromPoints([...corners, corners[0]]);
  return new THREE.Line(geom, new THREE.LineBasicMaterial({ color }));
}

const xCorners = [
  mathToWorld(1, yMin, zMin),
  mathToWorld(1, yMax, zMin),
  mathToWorld(1, yMax, zMax),
  mathToWorld(1, yMin, zMax)
];

