const greenGlow = new THREE.Mesh(geometryFromCorners(expandedCorners(xCorners, 1.045)), makeGlowMaterial(COLORS.x));
const blueGlow = new THREE.Mesh(geometryFromCorners(expandedCorners(zCorners, 1.045)), makeGlowMaterial(COLORS.z));
redGlow.renderOrder = greenGlow.renderOrder = blueGlow.renderOrder = 8;
redGlow.visible = greenGlow.visible = blueGlow.visible = false;
root.add(redGlow, greenGlow, blueGlow);

const redOutline = makeOutline(yCorners, COLORS.yDark);
const greenOutline = makeOutline(xCorners, COLORS.xDark);
const blueOutline = makeOutline(zCorners, COLORS.zDark);
