}

function applyVisibility() {
  const sx = document.getElementById('showXPlane').checked;
  const sy = document.getElementById('showYPlane').checked;
  const sz = document.getElementById('showZPlane').checked;
  setPlaneVisibility('x', sx);
  setPlaneVisibility('y', sy);
  setPlaneVisibility('z', sz);
}

function clearSelection() {
  selectedPlane = null;
  redGlow.visible = greenGlow.visible = blueGlow.visible = false;
  redOutline.visible = greenOutline.visible = blueOutline.visible = false;
}

function selectPlane(name, announce = true) {
  selectedPlane = name;
  applyVisibility();
  if (announce) {
    if (name === 'x') showPopup('x = 1', 'The green sheet is the plane labeled x = 1 in the printed figure.');
    if (name === 'y') showPopup('y = −2', 'The red sheet is the plane labeled y = −2 in the printed figure.');
    if (name === 'z') showPopup('z = 2', 'The blue horizontal sheet is the plane labeled z = 2 in the printed figure.');
  }
}

xLabel.div.addEventListener('click', () => selectPlane('x'));
yLabel.div.addEventListener('click', () => selectPlane('y'));
zLabel.div.addEventListener('click', () => selectPlane('z'));

registerInteractive(greenPlane, {
  title: 'x = 1',
  tooltip: 'Click to highlight the green plane',
  body: 'This is the green plane labeled x = 1.',
  onClick: () => selectPlane('x')
});
registerInteractive(redPlane, {
  title: 'y = −2',
  tooltip: 'Click to highlight the red plane',
  body: 'This is the red plane labeled y = −2.',
