});
registerInteractive(bluePlane, {
  title: 'z = 2',
  tooltip: 'Click to highlight the blue plane',
  body: 'This is the blue horizontal plane labeled z = 2.',
  onClick: () => selectPlane('z')
});
registerInteractive(point, {
  title: '(1, −1, 2)',
  tooltip: 'Printed point label',
  body: 'The black point is labeled exactly as in the source figure: (1, −1, 2).'
});

function setTeachingNote(on) {
  document.getElementById('showTeachingNote').checked = on;
  noteLabel.div.style.visibility = on ? 'visible' : 'hidden';
  if (on) {
    document.getElementById('demoTitle').textContent = 'Teaching note';
    document.getElementById('demoText').textContent = 'The default view preserves the printed labels. This optional note points out that the printed point has y = −1 while the red plane label says y = −2.';
  } else {
    document.getElementById('demoTitle').textContent = 'Printed figure';
    document.getElementById('demoText').textContent = 'The source labels are shown directly: three colored coordinate planes and the labeled point.';
  }
}

function setActiveStep(i) {
  for (let j = 0; j < 4; j++) document.getElementById('step' + j).classList.toggle('active', j === i);
}

function resetPrintedView() {
  document.getElementById('showXPlane').checked = true;
  document.getElementById('showYPlane').checked = true;
  document.getElementById('showZPlane').checked = true;
  clearSelection();
  applyVisibility();
  setTeachingNote(false);
  setCameraView({
    projection: 'orthographic',
    azimuthDeg: 50,
    elevationDeg: 23,
    rollDeg: -7,
    heightFraction: 0.72,
    target: [0.18, 0.05, -0.18],
    distanceScale: 1.25
  });
}

document.getElementById('showXPlane').addEventListener('change', applyVisibility);
document.getElementById('showYPlane').addEventListener('change', applyVisibility);
document.getElementById('showZPlane').addEventListener('change', applyVisibility);
document.getElementById('showTeachingNote').addEventListener('change', e => setTeachingNote(e.target.checked));

document.getElementById('step0').addEventListener('click', () => {
  setActiveStep(0);
  resetPrintedView();
});
document.getElementById('step1').addEventListener('click', () => {
