  document.getElementById('showYPlane').checked = true;
  document.getElementById('showZPlane').checked = true;
  setTeachingNote(false);
  clearSelection();
  applyVisibility();
  document.getElementById('demoTitle').textContent = 'All three planes';
  document.getElementById('demoText').textContent = 'All three colored sheets overlap as in the printed source figure.';
});
document.getElementById('step3').addEventListener('click', () => {
  setActiveStep(3);
  document.getElementById('showXPlane').checked = true;
  document.getElementById('showYPlane').checked = true;
  document.getElementById('showZPlane').checked = true;
  clearSelection();
  applyVisibility();
  setTeachingNote(true);
});

function pulseHighlights() {
  requestAnimationFrame(pulseHighlights);
  pulseT += 0.045;
  const op = 0.20 + 0.08 * Math.sin(pulseT);
  redGlow.material.opacity = op;
  greenGlow.material.opacity = op;
  blueGlow.material.opacity = op;
}
pulseHighlights();

applyVisibility();
